using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using SplifyWin;
namespace Mcrf.Wpf {
 public sealed partial class MainWindow {
  UIElement ProfileTools(){var panel=new StackPanel{Margin=new Thickness(0,0,0,0)};var startup=new CheckBox{Content="Автозапуск Windows",IsChecked=startupEnabled,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,8,0,10)};startup.Click+=async(s,e)=>await Run(async()=>{bool requested=startup.IsChecked==true;try{await Task.Run(()=>WpfWindowsStartup.Set(requested,System.Reflection.Assembly.GetExecutingAssembly().Location));startupEnabled=requested;}finally{startup.IsChecked=startupEnabled;}});panel.Children.Add(startup);var actions=Button("Сброс",async()=>await Run(ProfileActions));actions.FontSize=11;actions.Padding=new Thickness(8,4,8,4);var keys=AsyncButton("Хоткеи",HotkeysDialog);keys.ToolTip="Глобальные горячие клавиши · назначаются нажатием";keys.MinWidth=80;keys.Padding=new Thickness(10,5,10,5);keys.Margin=new Thickness(0);panel.Children.Add(Columns(actions,keys));return panel;}
  async Task ProfileActions(){var window=Dialog("Сброс и восстановление",760,430);var panel=new StackPanel{Margin=new Thickness(20)};panel.Children.Add(Text("Операции относятся только к профилю MCRF. Движки будут остановлены; основной MCRF не изменяется. Записи в системном hosts общие с основным клиентом и меняются только при выборе опции ниже."));var choice=new ComboBox{ItemsSource=new[]{"Удалить настройки с резервной копией","Удалить настройки без резервной копии","Восстановить резервную копию"},SelectedIndex=0};panel.Children.Add(choice);var hosts=new CheckBox{Content="Также удалить / восстановить записи MCRF в системном hosts",Style=(Style)FindResource("LabeledPacketCheck"),IsChecked=false,Margin=new Thickness(0,12,0,12)};panel.Children.Add(hosts);panel.Children.Add(Toolbar(Button("Продолжить",()=>window.DialogResult=true),Button("Отмена",()=>window.DialogResult=false)));window.Content=panel;if(window.ShowDialog()!=true)return;int mode=choice.SelectedIndex;string folder=null;if(mode==2){using(var picker=new System.Windows.Forms.FolderBrowserDialog{Description="Папка резервной программе MCRF-профиля"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK)folder=picker.SelectedPath;if(folder==null)return;}if(!Confirm(mode==2?"Восстановить выбранную копию? Текущие настройки сохранятся в резервной копии.":mode==0?"Удалить текущие настройки, сохранив резервную копию?":"Удалить настройки без возможности восстановления?","Настройки"))return;if(hosts.IsChecked==true&&!Confirm("Это также изменит общие записи MCRF в системном hosts. Пользовательские записи останутся. Продолжить?","Общий системный hosts"))return;await session.ResetProfile(mode,folder,hosts.IsChecked==true);selectedProfile=null;RegisterHotkeys();RefreshAfterOperation("Главная");status.Text="Настройки WPF-профиля обновлены.";}
 }
}
